async function selectEntity(id){if(state.terrainBrush.active&&id!==state.terrainBrush.entityId)await stopTerrainEditing();state.selectedId=id;state.selectedIds=id?[id]:[];state.selectionAnchorId=id;const ent=await api().select_entity(id);renderOutliner();renderInspector(ent);renderScriptContext();renderStatus();if(ent?.components?.animation)setTimeout(()=>api()?.refresh_animation_info(ent.id),0);}
