  if(comps.render_attributes){const r=comps.render_attributes,cs=r.color_scale||[1,1,1,1];html+=`<div class="component-card component-editor" data-component-card="render_attributes">${componentHeader('Render Attributes',true,'render_attributes')}<div class="component-fields"><label class="component-check"><span>Enabled</span><input type="checkbox" data-render-check="enabled" ${r.enabled!==false?'checked':''}></label><label class="component-check"><span>Depth Test</span><input type="checkbox" data-render-check="depth_test" ${r.depth_test!==false?'checked':''}></label><label class="component-check"><span>Depth Write</span><input type="checkbox" data-render-check="depth_write" ${r.depth_write!==false?'checked':''}></label><label>Cull<select data-render-text="cull"><option value="inherit" ${r.cull==='inherit'?'selected':''}>Inherited</option><option value="back" ${(r.cull||'back')==='back'?'selected':''}>Back Faces</option><option value="front" ${r.cull==='front'?'selected':''}>Front Faces</option><option value="none" ${r.cull==='none'?'selected':''}>None / Two-sided</option></select></label><label>Transparency<select data-render-text="transparency"><option value="inherit" ${(r.transparency||'inherit')==='inherit'?'selected':''}>Inherited</option><option value="none" ${r.transparency==='none'?'selected':''}>None</option><option value="alpha" ${r.transparency==='alpha'?'selected':''}>Alpha</option><option value="binary" ${r.transparency==='binary'?'selected':''}>Binary</option><option value="multisample" ${r.transparency==='multisample'?'selected':''}>Multisample</option></select></label><label>Render Bin<select data-render-text="bin"><option value="inherit" ${(r.bin||'inherit')==='inherit'?'selected':''}>Inherited</option><option value="background" ${r.bin==='background'?'selected':''}>Background</option><option value="opaque" ${r.bin==='opaque'?'selected':''}>Opaque</option><option value="transparent" ${r.bin==='transparent'?'selected':''}>Transparent</option><option value="fixed" ${r.bin==='fixed'?'selected':''}>Fixed</option></select></label><label>Bin Sort<input type="number" step="1" data-render-number="sort" value="${Number(r.sort??0)}"></label><label>Depth Offset<input type="number" step="1" data-render-number="depth_offset" value="${Number(r.depth_offset??0)}"></label><label>Billboard<select data-render-text="billboard"><option value="none" ${(r.billboard||'none')==='none'?'selected':''}>None</option><option value="point_eye" ${r.billboard==='point_eye'?'selected':''}>Point Eye</option></select></label><label>Color Scale<input type="color" data-render-color value="${rgbToHex(cs)}"></label><label>Alpha Scale<input type="number" min="0" max="1" step=".05" data-render-alpha value="${Number(cs[3]??1)}"></label><label class="component-check"><span>Light Off</span><input type="checkbox" data-render-check="light_off" ${r.light_off?'checked':''}></label><label class="component-check"><span>Shader Off</span><input type="checkbox" data-render-check="shader_off" ${r.shader_off?'checked':''}></label><div class="component-note">Panda render state propagates down the entity subtree. Use this for deliberate overrides; leave Inherited where normal Material/World state should win.</div></div></div>`}
  if(comps.shader){const sh=comps.shader,inputs=sh.inputs||{};html+=`<div class="component-card component-editor" data-component-card="shader">${componentHeader('GLSL Shader',true,'shader')}<div class="component-fields"><label class="component-check"><span>Enabled</span><input type="checkbox" data-shader-check="enabled" ${sh.enabled!==false?'checked':''}></label><label class="asset-ref-label">Vertex Shader<span class="asset-ref-row"><input id="shaderVertexPath" data-shader-text="vertex" value="${escapeHtml(sh.vertex||'')}" placeholder="Pick .vert shader"><button type="button" data-inspector-shader-pick="vertex">Browse</button></span></label><label class="asset-ref-label">Fragment Shader<span class="asset-ref-row"><input id="shaderFragmentPath" data-shader-text="fragment" value="${escapeHtml(sh.fragment||'')}" placeholder="Pick .frag shader"><button type="button" data-inspector-shader-pick="fragment">Browse</button></span></label><label class="asset-ref-label">Geometry Shader<span class="asset-ref-row"><input id="shaderGeometryPath" data-shader-text="geometry" value="${escapeHtml(sh.geometry||'')}" placeholder="Optional"><button type="button" data-inspector-shader-pick="geometry">Browse</button></span></label><label>Shader Priority<input type="number" data-shader-number="priority" value="${Number(sh.priority??20)}"></label><label>Inputs · JSON<textarea data-shader-inputs rows="7" spellcheck="false">${escapeHtml(JSON.stringify(inputs,null,2))}</textarea></label><div class="component-actions"><button data-shader-open-workspace>Open Materials / Shaders</button><button data-shader-api>Shader API</button></div><div class="component-note">GLSL vertex + fragment files are applied through Panda3D <code>Shader.load(SL_GLSL)</code>. Inputs propagate through the entity subtree just like Panda shader inputs.</div></div></div>`}
