  const commitCollider=async()=>{const current=selected();if(!current?.components?.collider)return;const c=JSON.parse(JSON.stringify(current.components.collider));$$('[data-collider]').forEach(el=>{const key=el.dataset.collider;c[key]=el.tagName==='SELECT'?el.value:Math.max(0.01,parseFloat(el.value)||0.01)});$$('[data-collider-vector]').forEach(el=>{const key=el.dataset.colliderVector;c[key]=Array.isArray(c[key])?c[key].slice(0,3):[0,0,0];c[key][+el.dataset.axis]=parseFloat(el.value)||0});$$('[data-collider-int]').forEach(el=>c[el.dataset.colliderInt]=Math.max(0,Math.min(31,parseInt(el.value)||0)));const maskEl=$('[data-collider-mask]');if(maskEl){const raw=String(maskEl.value||'').trim();let v=Number(raw);if(!Number.isFinite(v))v=parseInt(raw,raw.toLowerCase().startsWith('0x')?16:10);c.mask=(Number.isFinite(v)?v:4294967295)>>>0}$$('[data-collider-check]').forEach(el=>c[el.dataset.colliderCheck]=!!el.checked);await commitComponent('collider',c)};$$('[data-collider],[data-collider-vector],[data-collider-int],[data-collider-mask],[data-collider-check]').forEach(inp=>inp.onchange=commitCollider);
