function bindInspectorInputs(){const commit=async()=>{const e=selected();if(!e)return;const transform=JSON.parse(JSON.stringify(e.transform));$$('[data-transform]').forEach(inp=>transform[inp.dataset.transform][+inp.dataset.axis]=parseFloat(inp.value)||0);const updated=await api().update_entity(e.id,{name:$('#entityName').value,enabled:$('#entityEnabled').checked,visible:$('#entityVisible').checked,transform});replaceEntity(updated);};$('#entityName').onchange=commit;$('#entityEnabled').onchange=commit;$('#entityVisible').onchange=commit;$$('[data-transform]').forEach(i=>i.onchange=commit);}
function replaceEntity(e){const i=state.scene.entities.findIndex(x=>x.id===e.id);if(i>=0)state.scene.entities[i]=e;renderOutliner();renderStatus();}
function renderStatus(){const count=(state.scene.entities||[]).length,sel=(state.selectedIds||[]).length;$('#entityCount').textContent=`${count} ${count===1?'Entity':'Entities'}${sel>1?` · ${sel} selected`:''}`;$('#sceneName').textContent=(state.scene.name||'Untitled')+'.pscene'+(state.sceneDirty?' *':'');$('#dirtyStatus').textContent=state.sceneDirty?'Modified':'Saved';$('#dirtyStatus').classList.toggle('dirty',!!state.sceneDirty);$('#undoBtn').disabled=!state.canUndo;$('#redoBtn').disabled=!state.canRedo;$('#editUndoBtn').disabled=!state.canUndo;$('#editRedoBtn').disabled=!state.canRedo;document.title=`${state.sceneDirty?'* ':''}Panda Editor — ${state.scene.name||'Untitled'}`;}
function renderSceneInfo(){$('#sceneInfo').innerHTML=`<b>Scene</b><span>${escapeHtml(state.scene.name||'Untitled')}</span><b>Format</b><span>.pscene v${state.scene.scene_version||1}</span><b>Entities</b><span>${(state.scene.entities||[]).length}</span><b>Runtime</b><span>Panda3D NodePath mirror</span>`;}
function updateScriptPanel(){
  const e=selected(),has=!!state.scriptPath;
  $('#scriptPath').textContent=has?state.scriptPath:(e?'No script attached to '+e.name:'No script attached');
  $('#saveScriptBtn').disabled=!has||state.runtimeState!=='stopped';
  $('#openFullScriptBtn').disabled=!has;
  $('#detachScriptBtn').disabled=!has||state.runtimeState!=='stopped';
  $('#addScriptBtn').disabled=!e||state.runtimeState!=='stopped';
  if(has)loadScript();else{$('#scriptEditor').value='';syncCodeHighlight($('#scriptEditor'),$('#scriptHighlight'));}
  renderScriptContext();
}
async function loadScript(){if(!state.scriptPath)return;try{const text=await api().read_text_file(state.scriptPath);$('#scriptEditor').value=text;syncCodeHighlight($('#scriptEditor'),$('#scriptHighlight'));if(state.workspaceScriptPath===state.scriptPath&&document.activeElement!==$('#workspaceScriptEditor')){$('#workspaceScriptEditor').value=text;updateWorkspaceLineNumbers()}}catch(e){log('Script load failed: '+e)}}
function mirrorScriptEditors(source){
  if(!state.scriptPath||state.workspaceScriptPath!==state.scriptPath)return;
  if(source==='quick'){$('#workspaceScriptEditor').value=$('#scriptEditor').value;$('#workspaceScriptState').textContent='Modified';updateWorkspaceLineNumbers();syncCodeHighlight($('#scriptEditor'),$('#scriptHighlight'))}
  else if(source==='workspace'){$('#scriptEditor').value=$('#workspaceScriptEditor').value;syncCodeHighlight($('#scriptEditor'),$('#scriptHighlight'))}
}
async function saveScript(){if(!state.scriptPath)return;const text=$('#scriptEditor').value;await api().write_text_file(state.scriptPath,text);if(state.workspaceScriptPath===state.scriptPath){$('#workspaceScriptEditor').value=text;$('#workspaceScriptState').textContent='Saved';updateWorkspaceLineNumbers()}toast('Script saved');}
async function addScript(){const e=selected();if(!e)return;const updated=await api().create_and_attach_script(e.id,'');replaceEntity(updated);state.scriptPath=updated.components?.script?.path||null;await refreshScriptFiles();renderInspector(updated);activateBottomTab('scripts');toast('New Python script created and attached');}
async function detachSelectedScript(){const e=selected();if(!e?.components?.script)return;const old=e.components.script.path;const updated=await api().detach_script_file(e.id);replaceEntity(updated);state.scriptPath=null;await refreshScriptFiles();renderInspector(updated);renderScriptContext();toast('Script detached; file kept in project');if(state.workspaceScriptPath===old)renderScriptAttachments((state.scriptFiles||[]).find(x=>x.path===old));}
async function attachOpenScriptToSelected(){const e=selected();if(!e||!state.workspaceScriptPath){toast('Select an entity and open a project script first');return}const updated=await api().attach_script_file(e.id,state.workspaceScriptPath,true);replaceEntity(updated);state.scriptPath=state.workspaceScriptPath;await refreshScriptFiles();renderInspector(updated);renderScriptContext();toast('Script attached to '+updated.name)}
function changed(payload){state.scene=payload.scene;state.selectedId=payload.selected_id;state.sceneDirty=payload.dirty??true;if(Object.prototype.hasOwnProperty.call(payload,'scene_path'))state.scenePath=payload.scene_path||'';state.canUndo=!!payload.can_undo;state.canRedo=!!payload.can_redo;const valid=new Set((state.scene.entities||[]).map(e=>e.id));state.selectedIds=(state.selectedIds||[]).filter(id=>valid.has(id));if(state.selectedId&&!state.selectedIds.includes(state.selectedId))state.selectedIds=[state.selectedId,...state.selectedIds];if(!state.selectedId&&state.selectedIds.length)state.selectedId=state.selectedIds.at(-1);state.validationLoaded=false;state.validationResult=null;renderAll();if(state.workspace==='scripting')refreshScriptFiles();if(state.workspace==='lighting')renderLightingWorkspace();if(state.workspace==='camera')renderCameraWorkspace();if(state.assets?.length)refreshAssets();}

