function viewportTransformPreview(payload){const e=(state.scene.entities||[]).find(x=>x.id===payload?.entity_id);if(!e||!payload.transform)return;e.transform=JSON.parse(JSON.stringify(payload.transform));if(state.selectedId!==e.id)return;$$('[data-transform]').forEach(inp=>{const key=inp.dataset.transform,axis=+inp.dataset.axis;const v=e.transform?.[key]?.[axis];if(Number.isFinite(v))inp.value=Number(v).toFixed(3)});}
