function updateRuntimeUI(){
  const active=state.runtimeState!=='stopped',paused=state.runtimeState==='paused';
  document.body.classList.toggle('runtime-active',active);
  $('#playBtn').classList.toggle('hidden',active);
  $('#pauseBtn').classList.toggle('hidden',!active);
  $('#stopBtn').classList.toggle('hidden',!active);
  $('#pauseBtn').textContent=paused?'▶ RESUME':'❚❚ PAUSE';
  const badge=$('#runtimeStatus');badge.classList.toggle('hidden',!active);badge.textContent=paused?'PAUSED':'PLAYING';
  $('#viewportStatus').textContent=active?(paused?'Runtime paused':'Runtime running'):(state.previewCameraId?'Scene camera preview':'Panda3D viewport');
  $$('[data-tool],#addEntityBtn,#addComponentBtn,#undoBtn,#redoBtn,#collisionHelpersBtn,#wireframeBtn,#projectionBtn,#cameraPresetSelect').forEach(el=>el.disabled=active);
  $('#scriptEditor').readOnly=active;$('#saveScriptBtn').disabled=active||!state.scriptPath;$('#workspaceScriptEditor').readOnly=active;$('#workspaceSaveScriptBtn').disabled=active||!state.workspaceScriptPath;
}
