let viewportSyncTimer=null;
function reportViewport(){
  const host=state.workspace==='vfx'?$('#vfxPreviewHost'):state.workspace==='materials'?$('#materialPreviewHost'):$('#viewportHost');
  if(!host||!['level','vfx','materials'].includes(state.workspace))return;
  const r=host.getBoundingClientRect(),dpr=window.devicePixelRatio||1;
  if(r.width<120||r.height<100)return;

  // The Panda viewport is a real native child window, not an HTML element.  It must
  // therefore be clipped explicitly when a scrollable workspace moves its HTML host
  // partly (or completely) outside the visible browser area.  Previously an off-screen
  // VFX host returned early here and left the native child at its last position, which
  // made the preview appear to stick to the top/bottom of the workspace.
  const rect={x:Math.round(r.left*dpr),y:Math.round(r.top*dpr),width:Math.round(r.width*dpr),height:Math.round(r.height*dpr),pixel_ratio:dpr};
  api()?.set_viewport_rect(rect);

  const clipTop=Math.max(r.top,0),clipBottom=Math.min(r.bottom,window.innerHeight),clipLeft=Math.max(r.left,0),clipRight=Math.min(r.right,window.innerWidth);
  const visible=clipRight>clipLeft&&clipBottom>clipTop;
  const clip=visible
    ? {x:Math.max(0,Math.round((clipLeft-r.left)*dpr)),y:Math.max(0,Math.round((clipTop-r.top)*dpr)),width:Math.max(0,Math.round((clipRight-clipLeft)*dpr)),height:Math.max(0,Math.round((clipBottom-clipTop)*dpr))}
    : {x:0,y:0,width:0,height:0};
  api()?.set_viewport_clip(clip);
}
function scheduleViewportSync(){clearTimeout(viewportSyncTimer);requestAnimationFrame(()=>requestAnimationFrame(reportViewport));viewportSyncTimer=setTimeout(reportViewport,90);}

function setViewportVisible(visible){try{api()?.set_viewport_visible(!!visible)}catch(_){}}
function setViewportExclusions(rects=[]){try{api()?.set_viewport_exclusions(rects)}catch(_){}}
function clipPopoverFromViewport(el){
  const vr=$('#viewportHost').getBoundingClientRect(),pr=el.getBoundingClientRect(),dpr=window.devicePixelRatio||1;
  const left=Math.max(vr.left,pr.left),top=Math.max(vr.top,pr.top),right=Math.min(vr.right,pr.right),bottom=Math.min(vr.bottom,pr.bottom);
  if(right<=left||bottom<=top){setViewportExclusions([]);return}
  setViewportExclusions([{x:Math.round((left-vr.left)*dpr),y:Math.round((top-vr.top)*dpr),width:Math.round((right-left)*dpr),height:Math.round((bottom-top)*dpr)}]);
}

