let componentBrowserCategory='All',componentBrowserFocus=-1;
function componentStorageKey(){return 'pandaEditor.recentComponents'}
function componentRecentKinds(){try{return JSON.parse(localStorage.getItem(componentStorageKey())||'[]').filter(x=>typeof x==='string').slice(0,6)}catch(_){return[]}}
function rememberComponentKind(kind){try{const next=[kind,...componentRecentKinds().filter(x=>x!==kind)].slice(0,6);localStorage.setItem(componentStorageKey(),JSON.stringify(next))}catch(_){}}
function componentBackingKey(kind){return ['point_light','spot_light','directional_light'].includes(kind)?'light':(kind.startsWith('ui_')?'ui':kind)}
function componentAlreadyAdded(entity,kind){return !!entity?.components?.[componentBackingKey(kind)]}
function componentCategories(){return ['All','Recent',...Array.from(new Set(COMPONENT_BROWSER_ITEMS.map(x=>x.category)))]}
function renderComponentBrowser(){
  const list=$('#componentBrowserList'),bar=$('#componentCategoryBar'),search=$('#componentSearch'),entity=selected();if(!list||!bar)return;
  const q=String(search?.value||'').trim().toLowerCase(),recent=componentRecentKinds();
  bar.innerHTML=componentCategories().map(c=>`<button type="button" data-component-category="${escapeHtml(c)}" class="${componentBrowserCategory===c?'active':''}">${escapeHtml(c)}</button>`).join('');
  let items=COMPONENT_BROWSER_ITEMS.filter(item=>{
    if(componentBrowserCategory==='Recent'&&!recent.includes(item.kind))return false;
    if(componentBrowserCategory!=='All'&&componentBrowserCategory!=='Recent'&&item.category!==componentBrowserCategory)return false;
    if(!q)return true;const hay=`${item.name} ${item.category} ${item.desc} ${item.keywords||''}`.toLowerCase();return hay.includes(q);
  });
  if(componentBrowserCategory==='Recent')items.sort((a,b)=>recent.indexOf(a.kind)-recent.indexOf(b.kind));
  const groups=[];for(const item of items){const group=componentBrowserCategory==='Recent'?'Recent':item.category;let g=groups.find(x=>x.name===group);if(!g){g={name:group,items:[]};groups.push(g)}g.items.push(item)}
  if(!groups.length){list.innerHTML=`<div class="component-browser-empty"><b>No matching components</b>Try a different search or category.</div>`;componentBrowserFocus=-1;updateComponentBrowserStatus();return}
  list.innerHTML=groups.map(g=>`<section class="component-browser-group"><div class="component-browser-group-title">${escapeHtml(g.name.toUpperCase())}</div>${g.items.map(item=>{const added=componentAlreadyAdded(entity,item.kind),isRecent=recent.includes(item.kind);return `<button type="button" class="component-browser-item" data-component-add="${escapeHtml(item.kind)}" ${added?'disabled':''} title="${escapeHtml(item.desc)}"><span class="component-browser-icon">${escapeHtml(item.icon)}</span><span class="component-browser-name">${escapeHtml(item.name)}</span><span class="component-browser-desc">${escapeHtml(item.desc)}</span>${added?'<span class="component-browser-badge">Added</span>':(isRecent?'<span class="component-browser-badge recent">Recent</span>':'')}</button>`}).join('')}</section>`).join('');
  componentBrowserFocus=-1;updateComponentBrowserStatus();
}
function updateComponentBrowserStatus(text=''){const status=$('#componentBrowserStatus');if(!status)return;const available=$$('#componentBrowserList .component-browser-item:not(:disabled)');status.textContent=text||(available.length?`${available.length} available · already-added components are disabled.`:'No addable component in this view.');}
function componentBrowserButtons(){return $$('#componentBrowserList .component-browser-item:not(:disabled)')}
function focusComponentBrowserIndex(index){const buttons=componentBrowserButtons();buttons.forEach(b=>b.classList.remove('keyboard-focus'));if(!buttons.length){componentBrowserFocus=-1;return}componentBrowserFocus=(index+buttons.length)%buttons.length;const b=buttons[componentBrowserFocus];b.classList.add('keyboard-focus');b.scrollIntoView({block:'nearest'});updateComponentBrowserStatus(b.querySelector('.component-browser-desc')?.textContent||'')}
async function addComponentFromBrowser(kind){const e=selected();if(!e||!kind)return;const item=COMPONENT_BROWSER_ITEMS.find(x=>x.kind===kind);if(componentAlreadyAdded(e,kind)){updateComponentBrowserStatus(`${item?.name||'Component'} is already on ${e.name}.`);return}const updated=await api().add_component(e.id,kind);if(updated?.id){rememberComponentKind(kind);replaceEntity(updated);renderInspector(updated);toast(`${item?.name||'Component'} added to ${updated.name}`)}closePopovers()}
function openComponentBrowser(anchor){const e=selected();if(!e){toast('Select an entity before adding a component');return}componentBrowserCategory='All';componentBrowserFocus=-1;$('#componentSearch').value='';$('#componentBrowserEntity').textContent=e.name;renderComponentBrowser();showPopover($('#componentMenu'),anchor);requestAnimationFrame(()=>$('#componentSearch')?.focus())}
function handleComponentBrowserKey(e){if($('#componentMenu')?.classList.contains('hidden'))return;if(e.key==='Escape'){e.preventDefault();closePopovers();return}if(e.key==='ArrowDown'){e.preventDefault();focusComponentBrowserIndex(componentBrowserFocus+1);return}if(e.key==='ArrowUp'){e.preventDefault();focusComponentBrowserIndex(componentBrowserFocus-1);return}if(e.key==='Enter'){const buttons=componentBrowserButtons();if(componentBrowserFocus>=0&&buttons[componentBrowserFocus]){e.preventDefault();addComponentFromBrowser(buttons[componentBrowserFocus].dataset.componentAdd)}return}}

function activateBottomTab(name){$$('#bottomTabs button').forEach(b=>b.classList.toggle('active',b.dataset.tab===name));$$('.tab-pane').forEach(p=>p.classList.toggle('active',p.id===`tab-${name}`));if(name==='console')requestAnimationFrame(()=>scrollOutputToBottom());}
function showPopover(el,anchor){const r=anchor.getBoundingClientRect();$$('.popover').forEach(p=>p.classList.add('hidden'));el.classList.remove('hidden');const margin=6,w=el.offsetWidth||190,h=el.offsetHeight||120;let left=Math.min(r.left,window.innerWidth-w-margin);left=Math.max(margin,left);let top=r.bottom+2;if(top+h>window.innerHeight-margin)top=Math.max(margin,r.top-h-2);el.style.left=`${left}px`;el.style.top=`${top}px`;requestAnimationFrame(()=>clipPopoverFromViewport(el))}
function closePopovers(){$$('.popover').forEach(p=>p.classList.add('hidden'));setViewportExclusions([]);scheduleViewportSync()}
function restoreViewportAfterDialog(){if(['level','vfx','materials'].includes(state.workspace)&&$('#settingsModal').classList.contains('hidden')&&$('#projectSettingsModal').classList.contains('hidden')){setViewportVisible(true);scheduleViewportSync()}}
let appDialogResolver=null;
function closeAppDialog(result=null){const modal=$('#appDialogModal');if(!modal||modal.classList.contains('hidden'))return;modal.classList.add('hidden');const resolve=appDialogResolver;appDialogResolver=null;restoreViewportAfterDialog();if(resolve)resolve(result)}
function showAppDialog(options={}){closePopovers();setViewportVisible(false);const modal=$('#appDialogModal'),card=modal.querySelector('.app-dialog-card'),input=$('#appDialogInput');const type=options.type||'confirm',kind=options.kind||'normal';card.dataset.kind=kind;$('#appDialogEyebrow').textContent=options.eyebrow||'PANDA EDITOR';$('#appDialogTitle').textContent=options.title||'Panda Editor';$('#appDialogMessage').textContent=options.message||'';const detail=$('#appDialogDetail');detail.textContent=options.detail||'';detail.classList.toggle('hidden',!options.detail);$('#appDialogIcon').textContent=options.icon||(kind==='danger'?'!':type==='prompt'?'✎':'?');input.classList.toggle('hidden',type!=='prompt');input.value=options.value??'';input.placeholder=options.placeholder||'';const cancel=$('#appDialogCancel');cancel.classList.toggle('hidden',type==='alert');cancel.textContent=options.cancelText||'Cancel';const alt=$('#appDialogAlt');alt.classList.toggle('hidden',!options.altText);alt.textContent=options.altText||'';const ok=$('#appDialogConfirm');ok.textContent=options.confirmText||'OK';modal.classList.remove('hidden');return new Promise(resolve=>{appDialogResolver=resolve;requestAnimationFrame(()=>{if(type==='prompt'){input.focus();input.select()}else ok.focus()})})}
async function appConfirm(message,options={}){return (await showAppDialog({...options,type:'confirm',message}))===true}
async function appPrompt(message,value='',options={}){const r=await showAppDialog({...options,type:'prompt',message,value});return typeof r==='string'?r:null}
async function appAlert(message,options={}){await showAppDialog({...options,type:'alert',message});return true}
async function confirmSceneTransition(action='continue'){
  const status=await api().scene_status();state.sceneDirty=!!status?.dirty;renderStatus();if(!state.sceneDirty)return true;
  const result=await showAppDialog({type:'confirm',title:'Unsaved Scene Changes',icon:'*',message:`Save changes to ${(state.scene.name||'Untitled')}.pscene before you ${action}?`,detail:'Save keeps your authoring changes. Don\'t Save continues without writing them. Cancel keeps the current scene open.',confirmText:'Save',altText:"Don't Save",cancelText:'Cancel'});
  if(result===true){const path=await api().save_scene();if(!path)return false;state.sceneDirty=false;renderStatus();return true}
  return result==='alt';
}
async function adoptLoadedScene(scene){
  if(!scene?.entities)return false;
  state.scene=scene;state.selectedId=null;state.selectedIds=[];state.selectionAnchorId=null;
  try{const status=await api().scene_status();state.sceneDirty=!!status?.dirty;state.scenePath=status?.path||'';state.canUndo=!!status?.can_undo;state.canRedo=!!status?.can_redo}catch(_){state.sceneDirty=false;state.canUndo=false;state.canRedo=false}
  state.validationLoaded=false;state.validationResult=null;
  renderAll();renderProblems();
  try{await refreshAssets()}catch(_){}
  return true;
}


function uiHudItems(){const q=($('#uiHudSearch')?.value||'').trim().toLowerCase();return(state.scene.entities||[]).filter(e=>e.components?.ui&&(!q||e.name.toLowerCase().includes(q)||String(e.components.ui.type||'').includes(q)))}
function uiHudReferenceSize(){const p=state.projectSettings||{};return [Math.max(320,Number(p.game_window_width)||1280),Math.max(240,Number(p.game_window_height)||720)]}
function uiHudAnchorBase(anchor,size=[0,0],W=1280,H=720){const w=Number(size?.[0]||0),h=Number(size?.[1]||0);const map={center:[W/2,H/2],top:[W/2,h/2],bottom:[W/2,H-h/2],left:[w/2,H/2],right:[W-w/2,H/2],top_left:[w/2,h/2],top_right:[W-w/2,h/2],bottom_left:[w/2,H-h/2],bottom_right:[W-w/2,H-h/2]};return map[anchor]||map.center}
function uiHudBounds(u,W=1280,H=720){const size=u.size||[240,80],base=uiHudAnchorBase(u.anchor||'center',size,W,H),off=u.offset||[0,0],w=Math.max(2,Number(size[0]||2)),h=Math.max(2,Number(size[1]||2));return{x:base[0]+Number(off[0]||0)-w/2,y:base[1]+Number(off[1]||0)-h/2,w,h}}
function uiHudSnapValue(v){const step=Math.max(1,Number(state.uiHudSnap)||1);return Math.round(v/step)*step}
function uiHudValidation(u){const out=[],type=String(u?.type||'ui').toLowerCase(),sz=u?.size||[0,0];if(type!=='canvas'&&(Number(sz[0]||0)<8||Number(sz[1]||0)<8))out.push({kind:'error',text:'Width and height must be at least 8 px.'});if(type==='slider'){const mn=Number(u.min_value??0),mx=Number(u.max_value??100),v=Number(u.value??mn);if(!(mx>mn))out.push({kind:'error',text:'Slider Max must be greater than Min.'});else if(v<mn||v>mx)out.push({kind:'warning',text:'Slider Value is outside its Min/Max range.'})}if(type==='progress'){const r=Number(u.range??100),v=Number(u.value??0);if(!(r>0))out.push({kind:'error',text:'Progress Range must be greater than zero.'});else if(v<0||v>r)out.push({kind:'warning',text:'Progress Value will be clamped to its Range at runtime.'})}if(type==='dropdown'){const opts=Array.isArray(u.options)?u.options:[];if(!opts.length)out.push({kind:'error',text:'Dropdown needs at least one option.'});else if(Number(u.selected_index??0)<0||Number(u.selected_index??0)>=opts.length)out.push({kind:'warning',text:'Selected Index is outside the current option list.'})}if(type==='radio'&&!String(u.group||'').trim())out.push({kind:'warning',text:'Radio controls should use a non-empty group name.'});if(['button','checkbox','slider','input','dropdown','radio'].includes(type)&&!String(u.signal_name||'').trim())out.push({kind:'warning',text:'Interactive UI has no Signal Name; the runtime fallback will be used.'});return out}
