  if($('#uiHudEntityList'))$('#uiHudEntityList').innerHTML=items.map(e=>{const u=e.components.ui||{};return `<div class="ui-hud-entity ${e.id===state.selectedId?'active':''}" data-ui-entity="${escapeHtml(e.id)}"><button class="ui-hud-entity-main" data-ui-select="${escapeHtml(e.id)}"><span>${iconFor(e)}</span><div><b>${escapeHtml(e.name)}</b><small>${escapeHtml(u.type||'ui')} · ${escapeHtml((u.anchor||'center').replaceAll('_',' '))}</small></div></button><button class="ui-hud-eye" data-ui-visibility="${escapeHtml(e.id)}" title="Toggle authored visibility">${u.visible!==false?'◉':'○'}</button></div>`}).join('')||'<div class="api-empty">No matching UI entities.</div>';
