  $('#uiHudZoomLabel').textContent=Math.round(zoom*100)+'%';$('#uiHudSnapLabel').textContent=`${state.uiHudSnap}px`;$('#uiHudGridBtn').classList.toggle('active',state.uiHudShowGrid);if($('#uiHudSafeBtn'))$('#uiHudSafeBtn').classList.toggle('active',state.uiHudShowSafe);const runtime=$('#uiHudRuntimeParity');if(runtime){const issueCount=items.reduce((n,e)=>n+uiHudValidation(e.components.ui||{}).length,0);runtime.textContent=issueCount?`Runtime parity · ${issueCount} authoring warning${issueCount===1?'':'s'}`:'Runtime parity · DirectGUI checks clean';runtime.className=issueCount?'warning':''}
