function beginUiHudDrag(ev,id){if(ev.button!==0||ev.target.closest('[data-ui-resize]'))return;ev.preventDefault();ev.stopPropagation();const e=(state.scene.entities||[]).find(x=>x.id===id);if(!e?.components?.ui||e.components.ui.type==='canvas')return;if(state.selectedId!==id){state.selectedId=id;api().select_entity(id)}const zoom=Number(state.uiHudZoom)||.7,start=[ev.clientX,ev.clientY],orig=[...(e.components.ui.offset||[0,0])];const move=m=>{const cur=(state.scene.entities||[]).find(x=>x.id===id);if(!cur)return;const u=JSON.parse(JSON.stringify(cur.components.ui));u.offset=[uiHudSnapValue(orig[0]+(m.clientX-start[0])/zoom),uiHudSnapValue(orig[1]+(m.clientY-start[1])/zoom)];cur.components.ui=u;renderUiHudDesigner();renderUiHudSelection()};const up=async m=>{window.removeEventListener('mousemove',move);window.removeEventListener('mouseup',up);const cur=(state.scene.entities||[]).find(x=>x.id===id);if(cur)await updateUiHudComponent(id,cur.components.ui)};window.addEventListener('mousemove',move);window.addEventListener('mouseup',up)}
