function intervalTimelineHtml(iv,ci){const total=Math.max(.001,intervalClipDuration(iv)),steps=iv.steps||[],parallel=(iv.composition||'sequence')==='parallel',major=total<=5?1:total<=15?2:5,ruler=[];for(let t=0;t<=total+.0001;t+=major)ruler.push(`<span style="left:${Math.min(100,t/total*100)}%">${t.toFixed(t<10?1:0)}s</span>`);const lanes=steps.map((st,si)=>{const start=intervalStepStart(iv,si),dur=Math.max(0,Number(st.duration)||0),left=Math.min(100,start/total*100),width=Math.max(1.2,Math.min(100-left,(dur||total*.025)/total*100)),selected=state.intervalsClipIndex===ci&&state.intervalsStepIndex===si,top=parallel?8+si*34:8;return `<button class="interval-timeline-block ${selected?'selected':''}" data-interval-timeline-step="${ci}:${si}" style="--iv-left:${left}%;--iv-width:${width}%;--iv-color:${intervalStepColor(st.type||'wait')};top:${top}px" title="${escapeHtml((st.type||'wait')+' · '+start.toFixed(2)+'s · '+dur.toFixed(2)+'s')}"><b>${escapeHtml((st.type||'wait').toUpperCase())}</b><small>${dur.toFixed(2)}s</small></button>`}).join('');return `<div class="interval-timeline"><div class="interval-timeline-head"><b>AUTHORING TIMELINE</b><span>${parallel?'PARALLEL':'SEQUENCE'} · ${total.toFixed(2)} sec</span></div><div class="interval-ruler">${ruler.join('')}</div><div class="interval-tracks ${parallel?'parallel':''}" style="min-height:${parallel?Math.max(46,16+steps.length*34):46}px">${lanes||'<span class="muted">Add a step to populate the timeline.</span>'}</div></div>`}
