const collect=()=>{const out=JSON.parse(JSON.stringify(c));out.enabled=$('#intervalsEnabled')?.checked!==false;out.clips=clips.map((iv,ci)=>{const n={...iv,name:$(`[data-iv-name="${ci}"]`)?.value.trim()||'Interval',composition:$(`[data-iv-composition="${ci}"]`)?.value||'sequence',play_rate:Math.max(.01,Number($(`[data-iv-rate="${ci}"]`)?.value)||1),autostart:!!$(`[data-iv-autostart="${ci}"]`)?.checked,loop:!!$(`[data-iv-loop="${ci}"]`)?.checked,finished_event:$(`[data-iv-finished-event="${ci}"]`)?.value.trim()||'',finished_signal:$(`[data-iv-finished-signal="${ci}"]`)?.value.trim()||''};n.steps=(iv.steps||[]).map((st,si)=>{const k=`${ci}:${si}`,typ=$(`[data-iv-step-type="${k}"]`)?.value||'wait',raw=$(`[data-iv-step-value="${k}"]`)?.value.trim()||'',x={...st,type:typ,duration:Math.max(0,Number($(`[data-iv-step-duration="${k}"]`)?.value)||0),target:$(`[data-iv-step-target="${k}"]`)?.value.trim()||'self',blend:$(`[data-iv-step-blend="${k}"]`)?.value||'easeInOut'};if(['move','rotate','scale'].includes(typ))x.to=raw.split(',').map(Number).concat([0,0,0]).slice(0,3);else if(typ==='event')x.event=raw;else if(typ==='signal')x.signal=raw;else if(['animation','sound'].includes(typ))x.clip=raw;return x});return n});return out};
