  $$('[data-ai-behavior-id]').forEach(b=>b.onclick=async()=>{state.aiBehaviorSelectedId=b.dataset.aiBehaviorId;state.selectedId=b.dataset.aiBehaviorId;await api().select_entity(state.selectedId);renderAiBehaviorWorkspace()});
