async function renameSelectedAsset(a){const name=await appPrompt('Rename the selected project asset.',a.name,{title:'Rename Asset',icon:'✎',confirmText:'Rename',detail:a.path});if(!name||name===a.name)return;const r=await api().rename_asset(a.path,name);if(!r?.ok){toast(`Rename failed: ${r?.reason||'unknown'}`);return}state.assetSelected=r.asset.path;await refreshAssets();await refreshScriptFiles();toast('Asset renamed')}
async function deleteSelectedAsset(a){if(a.reference_count){toast(`Asset is referenced by ${a.reference_count} scene object(s)`);return}if(!await appConfirm(`Delete ${a.name} from the project?`,{title:'Delete Asset',kind:'danger',confirmText:'Delete',detail:a.path}))return;const r=await api().delete_asset(a.path);if(!r?.ok){toast(r?.reason==='protected'?'Project templates are protected':'Asset could not be deleted');return}state.assetSelected=null;await refreshAssets();await refreshScriptFiles();toast('Asset deleted')}
async function importCurrentAsset(){let cat=state.assetCategory;if(cat==='all')cat='models';if(!['models','textures','audio'].includes(cat)){toast('Select Models, Textures or Audio to import');return}const item=await api().import_asset(cat);if(item?.path){state.assetSelected=item.path;await refreshAssets();toast(`${assetCategoryName(cat).replace(/s$/,'')} imported`)}}
