 value:{inputs:[],outputs:[['value','Value','float']]},
 texture:{inputs:[],outputs:[['color','Color','color'],['alpha','Alpha','float']]},
 multiply:{inputs:[['a','A','color'],['b','B','color']],outputs:[['result','Result','color']]},
