async function shortcuts(e){
  if(!$('#appDialogModal').classList.contains('hidden')){if(e.key==='Escape'){e.preventDefault();closeAppDialog(null)}else if(e.key==='Enter'&&$('#appDialogInput').classList.contains('hidden')){e.preventDefault();closeAppDialog(true)}return}
  const ctrl=e.ctrlKey||e.metaKey,inCode=e.target===$('#workspaceScriptEditor')||e.target===$('#scriptEditor');if(inCode&&((ctrl&&['d','f','g','/'].includes(e.key.toLowerCase()))||e.key==='Tab'))return;
  if(ctrl&&e.key.toLowerCase()==='s'&&state.workspace==='scripting'&&!e.target.matches('input')){e.preventDefault();await saveWorkspaceScript();return}
  if(e.key==='F6'&&!e.target.matches('input,textarea')){e.preventDefault();if(state.runtimeState==='stopped')await startPlay();else await togglePause();return}else if(e.key==='F8'&&!e.target.matches('input,textarea')){e.preventDefault();if(state.runtimeState!=='stopped')await stopPlay();return}else if(state.runtimeState!=='stopped')return;
  if(ctrl&&e.key.toLowerCase()==='s'){e.preventDefault();const p=await api().save_scene();if(p)toast('Scene saved')}
  else if(ctrl&&e.key.toLowerCase()==='o'){e.preventDefault();if(await confirmSceneTransition('open another scene')){const opened=await api().open_scene();await adoptLoadedScene(opened)}}
  else if(ctrl&&e.key.toLowerCase()==='n'){e.preventDefault();if(await confirmSceneTransition('create a new scene')){await api().new_scene();state.selectedIds=[];state.selectedId=null;state.selectionAnchorId=null}}
  else if(ctrl&&e.shiftKey&&e.key.toLowerCase()==='z'){e.preventDefault();const x=await api().redo();if(x)toast('Redo: '+x)}
  else if(ctrl&&e.key.toLowerCase()==='z'){e.preventDefault();const x=await api().undo();if(x)toast('Undo: '+x)}
  else if(e.key==='Delete'&&!e.target.matches('input,textarea')){e.preventDefault();await deleteCurrentSelection()}
  else if(e.key==='.'&&!e.target.matches('input,textarea'))api().frame_selected()
  else if(e.key==='Home'&&!e.target.matches('input,textarea')){e.preventDefault();api().frame_all()}
  else if(ctrl&&e.key.toLowerCase()==='d'){e.preventDefault();await duplicateCurrentSelection()}
  else if(!e.target.matches('input,textarea')&&['q','g','r','s'].includes(e.key.toLowerCase())){const map={q:'select',g:'move',r:'rotate',s:'scale'},tool=map[e.key.toLowerCase()];setToolUI(tool);await api().set_viewport_tool(tool)}
}
async function runStandalone(){closePopovers();const r=await api().run_standalone(true);if(!r.ok){await appAlert(r.error||'Could not launch standalone runtime.',{title:'Run Standalone',detail:'Save the current scene first, then try again.',kind:'warning'});return}toast('Standalone Panda3D game launched')}
async function setStartupScene(){closePopovers();const r=await api().set_current_as_startup_scene();if(!r.ok){await appAlert(r.error||'Could not set startup scene.',{title:'Startup Scene',kind:'warning'});return}state.projectSettings=state.projectSettings||{};state.projectSettings.startup_scene=r.startup_scene;toast('Startup scene set: '+r.startup_scene)}
function setupSplitters(){let drag=null;$('#leftSplit').onmousedown=e=>drag={type:'left',x:e.clientX,start:state.leftWidth};$('#rightSplit').onmousedown=e=>drag={type:'right',x:e.clientX,start:state.rightWidth};$('#bottomSplit').onmousedown=e=>drag={type:'bottom',y:e.clientY,start:state.bottomHeight};document.addEventListener('mousemove',e=>{if(!drag)return;if(drag.type==='left')state.leftWidth=Math.max(180,Math.min(520,drag.start+e.clientX-drag.x));if(drag.type==='right')state.rightWidth=Math.max(240,Math.min(560,drag.start-(e.clientX-drag.x)));if(drag.type==='bottom')state.bottomHeight=Math.max(105,Math.min(520,drag.start-(e.clientY-drag.y)));applyLayout();scheduleViewportSync()});document.addEventListener('mouseup',async()=>{if(!drag)return;drag=null;state.settings.left_width=state.leftWidth;state.settings.right_width=state.rightWidth;state.settings.bottom_height=state.bottomHeight;await api().save_settings({left_width:state.leftWidth,right_width:state.rightWidth,bottom_height:state.bottomHeight})});}
function openSettings(){setViewportVisible(false);const s=state.settings;$('#themeSelect').value=s.theme||'midnight';$('#fontScale').value=s.font_scale||1;$('#uiScale').value=s.ui_scale||1;$('#showGrid').checked=s.show_grid!==false;$('#snapEnabled').checked=!!s.snap_enabled;$('#snapSize').value=s.snap_size||1;updateScaleLabels();$('#settingsModal').classList.remove('hidden')}
function updateScaleLabels(){$('#fontScaleValue').textContent=Math.round($('#fontScale').value*100)+'%';$('#uiScaleValue').textContent=Math.round($('#uiScale').value*100)+'%'}
$('#fontScale').oninput=updateScaleLabels;$('#uiScale').oninput=updateScaleLabels;
async function saveSettings(){const vals={theme:$('#themeSelect').value,font_scale:+$('#fontScale').value,ui_scale:+$('#uiScale').value,show_grid:$('#showGrid').checked,snap_enabled:$('#snapEnabled').checked,snap_size:+$('#snapSize').value};state.settings=await api().save_settings(vals);applySettings();$('#settingsModal').classList.add('hidden');setViewportVisible(true);scheduleViewportSync();toast('Settings saved')}

function openProjectSettings(){
  setViewportVisible(false);
  const p=state.projectSettings||{};const g=p.gravity||[0,0,-9.81];
  $('#startupScene').value=p.startup_scene||'';$('#gameWindowTitle').value=p.game_window_title||'Panda3D Game';$('#gameWindowWidth').value=p.game_window_width||1280;$('#gameWindowHeight').value=p.game_window_height||720;$('#gameFullscreen').checked=!!p.game_fullscreen;
  $('#gravityX').value=Number(g[0]??0);$('#gravityY').value=Number(g[1]??0);$('#gravityZ').value=Number(g[2]??-9.81);$('#audioMasterVolume').value=Math.round(Number(p.audio_master_volume??1)*100);$('#audioSfxVolume').value=Math.round(Number(p.audio_sfx_volume??1)*100);$('#audioMusicVolume').value=Math.round(Number(p.audio_music_volume??0.85)*100);
  const layers=(p.collision_layers||[]).slice(0,32);while(layers.length<32)layers.push('Layer '+layers.length);
  $('#collisionLayerSettings').innerHTML=layers.map((name,i)=>`<label class="layer-row"><span>${i}</span><input data-layer-name="${i}" value="${escapeHtml(name)}"></label>`).join('');
  renderInputActions();$('#projectSettingsModal').classList.remove('hidden');
}
function renderInputActions(){const actions=state.projectSettings?.input_actions||{};$('#inputActionSettings').innerHTML=Object.entries(actions).map(([name,keys])=>`<div class="input-action-row"><input data-action-name value="${escapeHtml(name)}" placeholder="action_name"><input data-action-keys value="${escapeHtml((keys||[]).join(', '))}" placeholder="w, up"><button data-remove-action title="Remove action">×</button></div>`).join('');$$('[data-remove-action]').forEach(b=>b.onclick=()=>b.parentElement.remove())}
function addInputActionRow(){const wrap=document.createElement('div');wrap.className='input-action-row';wrap.innerHTML='<input data-action-name value="new_action" placeholder="action_name"><input data-action-keys value="" placeholder="key1, key2"><button data-remove-action title="Remove action">×</button>';$('#inputActionSettings').appendChild(wrap);wrap.querySelector('[data-remove-action]').onclick=()=>wrap.remove();wrap.querySelector('[data-action-name]').focus()}
async function saveProjectSettings(){const layers=Array.from({length:32},(_,i)=>$(`[data-layer-name="${i}"]`)?.value?.trim()||`Layer ${i}`);const actions={};$$('.input-action-row').forEach(row=>{const name=row.querySelector('[data-action-name]')?.value?.trim();if(!name)return;actions[name]=(row.querySelector('[data-action-keys]')?.value||'').split(',').map(x=>x.trim().toLowerCase()).filter(Boolean)});const vals={startup_scene:$('#startupScene').value.trim(),game_window_title:$('#gameWindowTitle').value.trim()||'Panda3D Game',game_window_width:Math.max(320,parseInt($('#gameWindowWidth').value||1280,10)),game_window_height:Math.max(240,parseInt($('#gameWindowHeight').value||720,10)),game_fullscreen:$('#gameFullscreen').checked,gravity:[+$('#gravityX').value||0,+$('#gravityY').value||0,+$('#gravityZ').value||0],audio_master_volume:Math.max(0,Math.min(1,(+$('#audioMasterVolume').value||0)/100)),audio_sfx_volume:Math.max(0,Math.min(1,(+$('#audioSfxVolume').value||0)/100)),audio_music_volume:Math.max(0,Math.min(1,(+$('#audioMusicVolume').value||0)/100)),collision_layers:layers,input_actions:actions};state.projectSettings=await api().save_project_settings(vals);$('#projectSettingsModal').classList.add('hidden');setViewportVisible(true);scheduleViewportSync();renderInspector();toast('Project settings saved')}
